using System.Linq;
using NUnit.Framework;
using PlcTwin.Twin;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace PlcTwin.Tests
{
    /// <summary>Main.unity as generated by SceneBuilder (plan Step 5): every bound name, camera, root rotation, no missing scripts.</summary>
    public class SceneBindingTests
    {
        UnityEngine.SceneManagement.Scene scene;

        [OneTimeSetUp] public void Open() => scene = EditorSceneManager.OpenScene("Assets/Scenes/Main.unity", OpenSceneMode.Additive);
        [OneTimeTearDown] public void Close() => EditorSceneManager.CloseScene(scene, true);

        GameObject[] All() => scene.GetRootGameObjects().SelectMany(r => r.GetComponentsInChildren<Transform>(true)).Select(t => t.gameObject).ToArray();

        [Test]
        public void EveryBoundNameExistsOnce()
        {
            var view = All().Select(g => g.GetComponent<MpsView>()).Single(v => v != null);
            Assert.IsNotNull(view.Root);
            Assert.AreEqual("MPS", view.Root.name);
            var names = view.Root.GetComponentsInChildren<Transform>(true).Select(t => t.name).ToList();
            foreach (var n in MpsView.BoundNames) Assert.AreEqual(1, names.Count(x => x == n), n);
            Assert.IsNotNull(view.App);
            Assert.IsNotNull(view.Panel);
            Assert.IsNotNull(view.ChipMetalPrefab);
            Assert.IsNotNull(view.ChipNonmetalPrefab);
            Assert.IsNotNull(view.LampOn);
            Assert.IsNotNull(view.SwitchOff);
        }

        [Test]
        public void SwitchesAreClickableAndNothingElseIs()
        {
            var colliders = All().Where(g => g.GetComponent<Collider>() != null).Select(g => g.name).OrderBy(n => n).ToArray();
            CollectionAssert.AreEquivalent(MpsView.Switches.Select(s => s.name).ToArray(), colliders);
        }

        [Test]
        public void CameraAndRoot()
        {
            var cam = All().Select(g => g.GetComponent<Camera>()).Single(c => c != null);
            Assert.IsTrue(cam.orthographic);
            var v = PlcTwin.Twin.PlcTwinApp.Views[0];
            Assert.AreEqual(v.size, cam.orthographicSize, 1e-6f);
            Assert.AreEqual(0f, Vector3.Distance(v.pos, cam.transform.position), 1e-5f);
            Assert.Less(Quaternion.Angle(Quaternion.Euler(v.euler), cam.transform.rotation), 0.01f);
            var root = scene.GetRootGameObjects().Single(g => g.name == "MPS");
            Assert.Less(Quaternion.Angle(Quaternion.Euler(-90, 0, 0), root.transform.rotation), 0.01f);
        }

        [Test]
        public void NoMissingScripts()
        {
            foreach (var g in All()) Assert.AreEqual(0, GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(g), g.name);
        }

        [Test]
        public void PlayerSettingsWindowedResizable1387x1000()
        {
            Assert.AreEqual(1387, PlayerSettings.defaultScreenWidth);
            Assert.AreEqual(1000, PlayerSettings.defaultScreenHeight);
            Assert.AreEqual(FullScreenMode.Windowed, PlayerSettings.fullScreenMode);
            Assert.IsTrue(PlayerSettings.resizableWindow);
            Assert.IsTrue(PlayerSettings.runInBackground);
        }
    }
}
